using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change: HasData no longer accepts non-deterministic values
        // like DateTime.UtcNow. Use a fixed value instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    public DbSet<DiscountedProduct> DiscountedProducts => Set<DiscountedProduct>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "EfAppDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change #1: EF Core 9 renamed the discriminator property from
        // "Discriminator" to "$type". For existing documents that already use
        // "Discriminator", explicitly configure the old property name.
        modelBuilder.Entity<Product>()
            .HasDiscriminator<string>("Discriminator")
            .HasValue<Product>("Product")
            .HasValue<DiscountedProduct>("DiscountedProduct");

        modelBuilder.Entity<Product>().ToContainer("Products");
        modelBuilder.Entity<Product>().HasPartitionKey(p => p.Category);
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

class DiscountedProduct : Product
{
    public decimal Discount { get; set; }
}

// Breaking change #2: Synchronous Cosmos DB queries are no longer supported in
// EF Core 9. All queries must use async methods (ToListAsync, FirstOrDefaultAsync, etc.)
class CosmosQueryService
{
    private readonly CosmosDbContext _db;

    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BEFORE (EF Core 8 – worked synchronously):
    //   var products = _db.Products.Where(p => p.Category == "Electronics").ToList();
    //   var first = _db.Products.First();

    // AFTER (EF Core 9 – must use async):
    public async Task<List<Product>> GetProductsByCategoryAsync(string category)
    {
        return await _db.Products
            .Where(p => p.Category == category)
            .ToListAsync();
    }

    public async Task<Product?> GetFirstProductAsync()
    {
        return await _db.Products.FirstOrDefaultAsync();
    }
}

